  ctx.strokeStyle=color; ctx.lineWidth=2; ctx.beginPath()
  data.forEach((p,i)=>{ if(i===0) ctx.moveTo(sx(p.x),sy(p.y)); else ctx.lineTo(sx(p.x),sy(p.y)) })
  ctx.stroke()
